1. SELECT unit, COUNT(*) AS reading_count FROM sensor_readings GROUP BY unit ORDER BY unit;
2. SELECT sr.unit, COUNT(*) AS total_readings FROM sensor_readings sr JOIN assets a ON sr.asset_id = a.asset_id GROUP BY sr.unit ORDER BY sr.unit;
3. SELECT sr.unit, COUNT(*) AS num_readings FROM sensor_readings sr JOIN assets a ON sr.asset_id = a.asset_id JOIN locations l ON a.location_id = l.location_id GROUP BY sr.unit ORDER BY sr.unit;
